    private record DynamicFieldSeed(String category, String fieldKey, String displayName,
                                     String sampleValue, String description, int sortOrder) {
    }

    private static final List<DynamicFieldSeed> DYNAMIC_FIELDS = List.of(
            new DynamicFieldSeed("Community", "communityName", "Community Name", "Green Valley Apartments", "Current community name.", 10),
            new DynamicFieldSeed("Community", "logoUrl", "Logo URL", "https://cdn.example.com/logo.png", "Community logo from branding.", 20),
            new DynamicFieldSeed("Community", "primaryColor", "Primary Color", "#2563eb", "Community primary brand color.", 30),
            new DynamicFieldSeed("Community", "supportEmail", "Support Email", "support@manacommunity.app", "Community support email.", 40),
            new DynamicFieldSeed("Tournament", "tournamentName", "Tournament Name", "Summer Sports League", "Tournament display name.", 100),
            new DynamicFieldSeed("Tournament", "venue", "Venue", "Main Clubhouse Ground", "Tournament or match venue.", 110),
            new DynamicFieldSeed("Tournament", "date", "Date", "25 July 2026", "Tournament date.", 120),
            new DynamicFieldSeed("Tournament", "startTime", "Start Time", "9:00 AM", "Tournament start time.", 130),
            new DynamicFieldSeed("Tournament", "endTime", "End Time", "6:00 PM", "Tournament end time.", 140),
            new DynamicFieldSeed("Sports", "sportList", "Sport List", "Cricket, Badminton, Chess", "Comma separated sport list.", 200),
            new DynamicFieldSeed("Sports", "winners", "Winners", "Team A", "Winner list or summary.", 210),
            new DynamicFieldSeed("Payments", "amount", "Amount", "1500", "Payment or invoice amount.", 300),
            new DynamicFieldSeed("Payments", "invoiceNumber", "Invoice Number", "INV-2026-001", "Invoice reference.", 310),
            new DynamicFieldSeed("User", "firstName", "First Name", "Aarav", "Recipient first name.", 400),
            new DynamicFieldSeed("User", "lastName", "Last Name", "Sharma", "Recipient last name.", 410)
    );

    @Transactional
    public void seed() {
        log.info("Seeding default email templates...");
        seedDynamicFields();

        for (Community community : communityRepository.findAll()) {
            EmailHeader header = getOrCreateHeader(community);
            EmailFooter footer = getOrCreateFooter(community);
            for (TemplateSeed t : TEMPLATES) {
                getOrCreateTemplate(community, header, footer, t);
            }
        }
        log.info("Email templates seeded");
    }

    private EmailHeader getOrCreateHeader(Community community) {
        return headerRepository.findByCommunity_IdAndName(community.getId(), DEFAULT_HEADER_NAME)
                .orElseGet(() -> headerRepository.save(EmailHeader.builder()
                        .community(community)
                        .name(DEFAULT_HEADER_NAME)
                        .htmlContent(DEFAULT_HEADER_HTML)
                        .layoutJson(DEFAULT_HEADER_LAYOUT)
                        .active(true)
                        .version(1)
                        .build()));
    }

    private EmailFooter getOrCreateFooter(Community community) {
        return footerRepository.findByCommunity_IdAndName(community.getId(), DEFAULT_FOOTER_NAME)
                .orElseGet(() -> footerRepository.save(EmailFooter.builder()
                        .community(community)
                        .name(DEFAULT_FOOTER_NAME)
                        .htmlContent(DEFAULT_FOOTER_HTML)
                        .layoutJson(DEFAULT_FOOTER_LAYOUT)
                        .active(true)
                        .version(1)
                        .build()));
    }

    private void getOrCreateTemplate(Community community, EmailHeader header, EmailFooter footer, TemplateSeed t) {
        if (templateRepository.findByCommunity_IdAndTemplateCodeIgnoreCase(community.getId(), t.code()).isPresent()) {
            return;
        }
        EmailTemplateDefinition template = templateRepository.save(EmailTemplateDefinition.builder()
                .community(community)
                .templateCode(t.code())
                .templateName(t.name())
                .category(t.category())
                .subject(t.subject())
                .htmlContent(t.html())
                .layoutJson(t.layoutJson())
                .header(header)
                .footer(footer)
                .status(EmailTemplateStatus.ACTIVE)
                .version(1)
                .build());

        versionRepository.save(EmailTemplateVersion.builder()
                .template(template)
                .version(1)
                .subject(t.subject())
                .htmlContent(t.html())
                .layoutJson(t.layoutJson())
                .header(header)
                .footer(footer)
                .status(EmailTemplateStatus.ACTIVE)
                .notes("Initial database-backed sample template")
                .build());
    }

    private void seedDynamicFields() {
        for (DynamicFieldSeed f : DYNAMIC_FIELDS) {
            if (dynamicFieldRepository.findByFieldKey(f.fieldKey()).isPresent()) {
                continue;
            }
            dynamicFieldRepository.save(EmailDynamicField.builder()
                    .category(f.category())
                    .fieldKey(f.fieldKey())
                    .displayName(f.displayName())
                    .sampleValue(f.sampleValue())
                    .description(f.description())
                    .active(true)
                    .sortOrder(f.sortOrder())
                    .build());
        }
    }
